"""Canonical sizes. (height m, girth G where 1.0 = average human build, Gm = how broad the model's own cubes already are).
Generates entity/CreatureSizes.java: hitbox + extra render scale on top of each renderer's own scale. Run: python3 tools/sizes.py"""
import os, re
J = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'src/main/java/com/reevil/')
NATIVE = {'mrx': 2.31, 'nem': 2.4, 'gan': 2.03, 'zom': 2.0}   # visual height (blocks) of each rig at scale 1
RIGOF = {}
for r, ids in {'mrx': 'wesker jill heisenberg jack_baker verdugo ustanak dimitrescu sturm urias ndesu ogroman mendez el_gigante executioner_majini gnezdo daughter marguerite soldat mr_x re2r_mr_x re4r_el_gigante re4r_verdugo',
               'nem': 'nemesis re2r_nemesis re3r_nemesis miranda saddler simmons eveline',
               'gan': 'ganado zealot salvador chainsaw_majini majini gatling_majini javo molded krauser re4r_ganado re4r_krauser',
               'zom': 'zombie re1r_zombie re2r_zombie re3r_zombie pale_head re3r_pale_head armadura re4r_armadura iron_maiden re4r_iron_maiden regenerador re4r_regenerador fat_molded'}.items():
    for i in ids.split(): RIGOF[i] = r
# id: (T, G, Gm)
T = {
 'el_gigante': (7.0, 1.6, 1.4), 're4r_el_gigante': (7.0, 1.5, 1.0), 'ogroman': (9.0, 1.9, 1.5), 'executioner_majini': (2.35, 1.35, 1.33), 'ndesu': (2.9, 1.5, 1.0), 'sturm': (3.0, 1.9, 1.7), 'urias': (3.3, 1.7, 1.25),
 'dimitrescu': (2.9, 1.2, 0.9), 'mendez': (2.4, 1.3, 1.25), 'mr_x': (2.3, 1.3, 1.0), 're2r_mr_x': (2.4, 1.35, 1.2), 'nemesis': (2.5, 1.35, 1.0), 're2r_nemesis': (2.5, 1.35, 1.0), 're3r_nemesis': (2.6, 1.4, 1.1), 'ustanak': (2.6, 1.4, 1.0),
 'verdugo': (2.5, 0.95, 0.8), 're4r_verdugo': (2.6, 1.0, 1.0), 'jack_baker': (1.9, 1.35, 1.3), 'salvador': (1.96, 1.3, 1.0), 'chainsaw_majini': (1.82, 1.25, 1.0), 'iron_maiden': (2.26, 1.25, 1.3), 're4r_iron_maiden': (2.3, 1.3, 1.4),
 'regenerador': (2.26, 1.0, 1.0), 're4r_regenerador': (2.3, 1.0, 1.0), 'armadura': (2.0, 1.2, 1.0), 're4r_armadura': (2.1, 1.25, 1.1), 'fat_molded': (2.3, 1.9, 1.45), 'gatling_majini': (1.9, 1.2, 1.0),
 'wesker': (1.83, 1.0, 1.0), 'jill': (1.7, 0.95, 1.0), 'heisenberg': (1.85, 1.1, 1.0), 'simmons': (1.87, 1.0, 1.0), 'marguerite': (1.68, 0.95, 1.0), 'daughter': (2.0, 0.95, 1.0), 'gnezdo': (1.7, 0.9, 0.9),
 'krauser': (1.9, 1.1, 1.0), 're4r_krauser': (1.95, 1.15, 1.0), 'saddler': (1.9, 1.2, 1.3), 'miranda': (1.7, 1.0, 1.0), 'eveline': (1.56, 0.9, 1.0), 'soldat': (1.9, 1.1, 1.1),
 'ganado': (1.8, 1.0, 1.0), 're4r_ganado': (1.85, 1.05, 1.0), 'zealot': (1.8, 1.0, 1.0), 'majini': (1.8, 1.0, 1.0), 'javo': (1.85, 1.0, 1.0), 'molded': (2.1, 0.95, 1.0),
 'zombie': (1.8, 1.0, 1.0), 're1r_zombie': (1.8, 1.0, 1.0), 're2r_zombie': (1.8, 1.0, 1.0), 're3r_zombie': (1.8, 1.0, 1.0), 'pale_head': (2.1, 0.95, 1.0), 're3r_pale_head': (2.2, 0.95, 1.0),
}
MANUAL = {'del_lago': (6.0, 5.0, 5.5 / 2.6, 5.5 / 2.6), 'neptune': (1.8, 1.5, 1.4, 1.4),
  # measured model bounds (tools/ModelBounds.java) vs canon: alligator 10 m, chimera 6.1 ft, Yawn 40 ft, doberman 70 cm, wolf ~1.7 m, hunters ~1.8 m
  'alligator': (1.9, 1.9, 2.35, 2.35), 'chimera': (1.0, 1.9, 1.45, 1.45), 'yawn': (2.2, 1.8, 1.56, 1.56), 'cerberus': (0.6, 0.95, 0.65, 0.65), 'colmillos': (0.6, 0.95, 0.67, 0.67), 'adjule': (0.6, 0.95, 0.73, 0.73),
  'hunter': (0.7, 1.9, 0.78, 0.78), 'hunter_beta': (0.7, 1.85, 0.82, 0.82), 're1r_hunter': (0.7, 1.9, 0.78, 0.78), 're3r_hunter_beta': (0.7, 1.85, 0.78, 0.78), 'lycan': (0.8, 2.1, 0.8, 0.8)}   # hitW, hitH, extraXZ, extraY (Del Lago >20 m long, Neptune 16 ft)

def k0(i):
    pk = i.replace('_', ''); C = ''.join(x.capitalize() for x in i.split('_'))
    try: r = open(J + 'client/%s/%sRenderer.java' % (pk, C)).read()
    except Exception: return 1.0
    m = re.search(r'ps\.scale\(([0-9.]+)f', r); return float(m.group(1)) if m else 1.0

rows = []
for i, (t, g, gm) in T.items():
    sy = t / NATIVE[RIGOF[i]]; k = k0(i)
    if i == 'soldat': k = 1.0
    rows.append((i, max(0.55, round(0.3 * t * g, 2)), t, round(sy * g / gm / k, 3), round(sy / k, 3)))
for i, (w, h, ex, ey) in MANUAL.items(): rows.append((i, w, h, ex, ey))
L = ['package com.reevil.entity;', '', 'import java.util.Map;', '', '/** Generated by tools/sizes.py from canonical heights/builds: {hitW, hitH, extra render scale XZ, extra render scale Y} (extra scale multiplies the renderer\'s own scale). */',
     'public final class CreatureSizes {', '    private CreatureSizes() {}', '    public static final Map<String, float[]> SIZES = Map.ofEntries(']
L.append(',\n'.join('        Map.entry("%s", new float[]{%sf, %sf, %sf, %sf})' % r for r in rows))
L += ['    );', '    public static float[] of(String id) { return SIZES.get(id); }', '}']
open(J + 'entity/CreatureSizes.java', 'w').write('\n'.join(L) + '\n')
print(len(rows), 'sizes')
